import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Deploying and Operating CephFS for Scientific Applications at Fermilab - Alison Peisker","description":"","frontmatter":{"title":"Deploying and Operating CephFS for Scientific Applications at Fermilab - Alison Peisker","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["CephFS","Fermilab","Scientific Application","Storage Solution","Data Management"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Deploying_and_Operating_CephFS_for_Scientific_Applications_at_Fermilab_-_Alison_Peisker.md","filePath":"posts/2025/Deploying_and_Operating_CephFS_for_Scientific_Applications_at_Fermilab_-_Alison_Peisker.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Deploying_and_Operating_CephFS_for_Scientific_Applications_at_Fermilab_-_Alison_Peisker.md"};function n(l,e,s,_,p,g){return i(),r("div",null,[...e[0]||(e[0]=[t('<h3 id="fermilab-cephfs-部署与运维实践总结" tabindex="-1"><strong>Fermilab CephFS 部署与运维实践总结</strong> <a class="header-anchor" href="#fermilab-cephfs-部署与运维实践总结" aria-label="Permalink to &quot;**Fermilab CephFS 部署与运维实践总结**&quot;">​</a></h3><h4 id="_1-会议概述" tabindex="-1"><strong>1. 会议概述</strong> <a class="header-anchor" href="#_1-会议概述" aria-label="Permalink to &quot;**1. 会议概述**&quot;">​</a></h4><ul><li><strong>演讲者</strong>: Alison Peisker（Fermilab 软件开发工程师）</li><li><strong>主题</strong>: Fermilab 如何为科学应用部署和运维 CephFS</li><li><strong>背景</strong>: Fermilab 是美国高能物理和加速器科学的领先实验室，需要处理海量实验数据。</li></ul><h4 id="_2-fermilab-数据存储架构" tabindex="-1"><strong>2. Fermilab 数据存储架构</strong> <a class="header-anchor" href="#_2-fermilab-数据存储架构" aria-label="Permalink to &quot;**2. Fermilab 数据存储架构**&quot;">​</a></h4><ul><li><strong>主要组件</strong>: dcache（原始数据存储），磁带系统（长期存储），CephFS（交互式数据分析）</li><li><strong>数据流</strong>: 实验数据 → 数据采集系统 → dcache/磁带 → CephFS（用户分析）</li></ul><h4 id="_3-cephfs-集群选型与设计" tabindex="-1"><strong>3. CephFS 集群选型与设计</strong> <a class="header-anchor" href="#_3-cephfs-集群选型与设计" aria-label="Permalink to &quot;**3. CephFS 集群选型与设计**&quot;">​</a></h4><ul><li><strong>选择原因</strong>: 开源、活跃社区、POSIX 兼容、支持快照、硬件灵活性、扩展性</li><li><strong>集群规模</strong>: Head Nodes 5个，Storage Nodes 25个，Over 500 OSDs</li><li><strong>Pool 配置</strong>: 元数据池（4副本，NVMe），数据池（3副本，NVMe；EC 4+2 HDD；EC 8+3 HDD）</li></ul><h4 id="_4-部署与运维经验" tabindex="-1"><strong>4. 部署与运维经验</strong> <a class="header-anchor" href="#_4-部署与运维经验" aria-label="Permalink to &quot;**4. 部署与运维经验**&quot;">​</a></h4><ul><li><strong>部署工具</strong>: cephadm</li><li><strong>挑战与解决方案</strong>: 硬件故障（自动恢复），软件问题（社区修复），安全合规（自动化脚本）</li><li><strong>性能调优</strong>: 默认配置为主，调整 MDS 缓存内存限制、客户端自动驱逐</li></ul><h4 id="_5-自动化与监控" tabindex="-1"><strong>5. 自动化与监控</strong> <a class="header-anchor" href="#_5-自动化与监控" aria-label="Permalink to &quot;**5. 自动化与监控**&quot;">​</a></h4><ul><li><strong>内核更新工具</strong>: 逐节点重启，检查集群健康状态</li><li><strong>配额管理</strong>: 自定义脚本 + 配置文件，自动同步配额至监控页面</li><li><strong>监控看板</strong>: 展示各实验目录的存储使用量和配额占比</li></ul><h4 id="_6-未来计划" tabindex="-1"><strong>6. 未来计划</strong> <a class="header-anchor" href="#_6-未来计划" aria-label="Permalink to &quot;**6. 未来计划**&quot;">​</a></h4><ul><li><strong>对象存储</strong>: 用于科学数据</li><li><strong>块存储</strong>: 替换 dcache 的硬件 RAID 6</li><li><strong>数据流扩展</strong>: 通过 Globus/XD 工具实现跨实验室数据迁移</li></ul><h4 id="_7-总结" tabindex="-1"><strong>7. 总结</strong> <a class="header-anchor" href="#_7-总结" aria-label="Permalink to &quot;**7. 总结**&quot;">​</a></h4><p>CephFS 在 Fermilab 成功替代传统 NAS，满足科学计算的扩展性和灵活性需求。通过 cephadm 简化部署，结合自动化工具降低运维成本，未来将持续探索 Ceph 的多模态存储（对象/块）在科研场景中的应用。</p><p><strong>关键词保留</strong>: CephFS, POSIX, OSD, MON, MDS, EC (Erasure Coding), RADOS, PG, cephadm, kernel client, capability recall.</p>',16)])])}const d=a(o,[["render",n]]);export{c as __pageData,d as default};
